// layouts/default.vue
export default {
  mounted() {
    this.$nextTick(() => {
      const hasState = Object.keys(this.$auth.$storage._state).some(
        (key) => !!this.$auth.$storage._state[key],
      );
      if (this.$route.name !== 'callback' && !this.$auth.loggedIn && hasState) {
        this.$auth.refreshTokens().catch(() => this.$auth.logout());
      }
    });
  },
};
